  MESSAGES.en.ov_youReCloserTo = "You're closer to the goal. Fine-tune your pronunciation and intonation a bit!"; MESSAGES.vi.ov_youReCloserTo = "Bạn đã tiến gần hơn đến mục tiêu. Chỉnh thêm một chút phát âm và ngữ điệu nhé!"; MESSAGES.ko.ov_youReCloserTo = "목표에 더 가까워졌어요. 발음과 억양을 조금 더 다듬어 보세요!";
  MESSAGES.en.ov_youReDoingGreat = "You're doing great. Polish a few small details to make it smoother!"; MESSAGES.vi.ov_youReDoingGreat = "Bạn đang làm rất tốt. Chỉnh thêm vài chi tiết nhỏ để câu nói mượt mà hơn nhé!"; MESSAGES.ko.ov_youReDoingGreat = "아주 잘하고 있어요. 작은 부분 몇 가지만 다듬으면 더 매끄러워져요!";
  MESSAGES.en.ov_youReHalfwayThere = "You're halfway there. Push a little more to sound more natural!"; MESSAGES.vi.ov_youReHalfwayThere = "Một nửa chặng đường đã nằm trong tay bạn. Cố thêm chút nữa để lời nói tự nhiên hơn!"; MESSAGES.ko.ov_youReHalfwayThere = "절반은 이미 해냈어요. 조금만 더 노력해 자연스럽게 말해 보세요!";
  MESSAGES.en.ov_youReMasteringThe = "You're mastering the pronunciation. You sound like you've reached a new level!"; MESSAGES.vi.ov_youReMasteringThe = "Bạn đang làm chủ cách phát âm rất tốt. Nghe thôi đã thấy trình độ lên một tầm mới!"; MESSAGES.ko.ov_youReMasteringThe = "발음을 아주 잘 다루고 있어요. 듣기만 해도 실력이 한 단계 올라간 게 느껴져요!";
  MESSAGES.en.ov_youReVeryClose = "You're very close to a good score. A little more focus and you're there!"; MESSAGES.vi.ov_youReVeryClose = "Bạn đang rất gần mức tốt rồi. Thêm một chút tập trung là có thể chạm đích!"; MESSAGES.ko.ov_youReVeryClose = "좋은 점수에 거의 다 왔어요. 조금만 더 집중하면 도달할 수 있어요!";
  MESSAGES.en.ov_youSaidQuiteA = "You said quite a lot correctly. Keep practising each sound to be clearer!"; MESSAGES.vi.ov_youSaidQuiteA = "Bạn đã nói được kha khá đấy. Tiếp tục luyện từng âm để câu nói rõ ràng hơn nhé!"; MESSAGES.ko.ov_youSaidQuiteA = "꽤 많이 말했어요. 소리 하나하나를 계속 연습해 더 또렷하게 말해 보세요!";
  MESSAGES.en.ov_youSpokeClearlyAnd = "You spoke clearly and accurately. Now add some intonation to sound captivating!"; MESSAGES.vi.ov_youSpokeClearlyAnd = "Bạn đã nói rất rõ ràng và chính xác. Giờ hãy thêm chút ngữ điệu để nghe thật cuốn hút!"; MESSAGES.ko.ov_youSpokeClearlyAnd = "아주 또렷하고 정확하게 말했어요. 이제 억양을 더해 매력적으로 들리게 해 보세요!";
  MESSAGES.en.ov_youTypedTheWhole = "You typed the whole sentence correctly. Press Enter for the next one."; MESSAGES.vi.ov_youTypedTheWhole = "Bạn đã chép đúng cả câu. Nhấn Enter để sang câu tiếp."; MESSAGES.ko.ov_youTypedTheWhole = "문장 전체를 정확히 받아 적었어요. Enter를 눌러 다음 문장으로 가세요.";
  MESSAGES.en.ov_youVeGotMost = "You've got most of the pronunciation. Focus on the missing sounds to break through!"; MESSAGES.vi.ov_youVeGotMost = "Bạn đã nắm được phần lớn cách phát âm. Chú ý thêm những âm còn thiếu để bứt phá nhé!"; MESSAGES.ko.ov_youVeGotMost = "발음 대부분을 익혔어요. 빠진 소리에 집중해 한 단계 도약해 보세요!";
  MESSAGES.en.ov_youVeGotThe = "You've got the first sounds. Slow down a little, listen closely and try again!"; MESSAGES.vi.ov_youVeGotThe = "Bạn đã có những âm thanh đầu tiên. Chậm lại một chút, nghe kỹ và thử lại nhé!"; MESSAGES.ko.ov_youVeGotThe = "첫 소리를 냈어요. 조금 천천히, 잘 듣고 다시 해 보세요!";
  MESSAGES.en.ov_youVeReachedThe = "You've reached the speaking threshold. Keep practising to sound more natural!"; MESSAGES.vi.ov_youVeReachedThe = "Bạn đã đạt ngưỡng luyện nói. Luyện thêm để phát âm tự nhiên hơn nhé!"; MESSAGES.ko.ov_youVeReachedThe = "말하기 기준을 통과했어요. 더 연습해 자연스럽게 발음해 보세요!";
  MESSAGES.en.ov_youVeStarted = "You've started!"; MESSAGES.vi.ov_youVeStarted = "Đã bắt đầu rồi!"; MESSAGES.ko.ov_youVeStarted = "시작했어요!";
  MESSAGES.en.ov_yourPronunciationIsSolid = "Your pronunciation is solid. Keep it up and take on harder sentences!"; MESSAGES.vi.ov_yourPronunciationIsSolid = "Phát âm của bạn đã khá vững vàng. Tiếp tục duy trì phong độ và chinh phục những câu khó hơn!"; MESSAGES.ko.ov_yourPronunciationIsSolid = "발음이 꽤 탄탄해요. 이 기세로 더 어려운 문장에 도전해 보세요!";
