  MESSAGES.en.off_ofaT = "Oops, the internet dozed off!"; MESSAGES.vi.off_ofaT = "Ối, rớt mạng rồi!"; MESSAGES.ko.off_ofaT = "앗, 인터넷이 끊겼어요!";
